const $=(q,r=document)=>r.querySelector(q),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const wait=async(f,ms=18000)=>{const end=performance.now()+ms;while(performance.now()<end){const value=f();if(value)return value;await sleep(40);}throw Error('Tempo limite: '+f);};
