const read=frame=>{const w=frame.element.ownerDocument.defaultView,c=frame.composition;return {camera:w.getComputedStyle(c.camera).transform,jitter:w.getComputedStyle(c.jitter).transform,fx:c.planes.flatMap(p=>(p.effects??[]).map(e=>(()=>{const m=new DOMMatrix(w.getComputedStyle(e.node).transform);return [m.a,m.b,m.c,m.d,m.e/(e.node.offsetWidth||1),m.f/(e.node.offsetHeight||1)];})())),visibility:c.planes.filter(p=>p.entry.id!=='background').map(p=>w.getComputedStyle(p.visibility).opacity),lights:(c.directionLights??[]).map(p=>w.getComputedStyle(p.node).opacity),events:(c.lightEvents??[]).map(p=>w.getComputedStyle(p.node).opacity),videos:c.videos.map(v=>({active:v.active,time:v.video?.currentTime,paused:v.video?.paused,fallback:v.image?.hidden}))};};
const at=async(frame,t)=>{frame.pause();frame.seek(t);await sleep(80);return read(frame);};
